from __future__ import annotations

import base64
import gzip
import subprocess
from pathlib import Path

ROOT = Path("FushERP_Mobile_Phase5")
PATCH = gzip.decompress(base64.b64decode(""))

if not ROOT.is_dir():
    raise SystemExit("FushERP_Mobile_Phase5 not found")

build = (ROOT / "app/build.gradle.kts").read_text(encoding="utf-8")
if "versionCode = 48" not in build or "0.15.4.9-phase14.5-transfer-reversal" not in build:
    raise SystemExit("Phase 14.5.9 baseline not found")

schema = (ROOT / "app/src/main/java/com/fush/erp/data/FushDatabase.kt").read_text(encoding="utf-8")
if "version = 21" not in schema:
    raise SystemExit("Expected Room schema 21 baseline")

proc = subprocess.run(["patch", "-p1", "--forward", "--batch"], cwd=ROOT, input=PATCH)
if proc.returncode != 0:
    raise SystemExit(proc.returncode)

checks = {
    ROOT / "app/build.gradle.kts": ["versionCode = 49", "0.15.4.10-phase14.5-partial-purchase-returns"],
    ROOT / "app/src/main/java/com/fush/erp/domain/PurchaseMath.kt": ["PurchaseReturnDraftLine", "validateReturnDraft"],
    ROOT / "app/src/main/java/com/fush/erp/domain/PurchaseService.kt": ["PostPurchaseReturnRequest", "postPurchaseReturn", "lotMovementTimeline"],
    ROOT / "app/src/main/java/com/fush/erp/ui/screens/PurchaseScreens.kt": ["مرتجع مشتريات جزئي", "إرجاع كل المتبقي"],
    ROOT / "app/src/test/java/com/fush/erp/domain/PurchaseMathTest.kt": ["partialReturnDraftAcceptsMultipleInvoiceLines", "partialReturnDraftRejectsDuplicatePurchaseLine"],
    ROOT / "PHASE14_5_10_SCOPE.md": ["Partial Purchase Returns", "Room schema remains 21"],
}
for path, needles in checks.items():
    text = path.read_text(encoding="utf-8")
    for needle in needles:
        if needle not in text:
            raise SystemExit(f"Missing expected marker {needle!r} in {path}")

print("Phase 14.5.10 partial purchase returns patch applied and verified")
